package com.gymmind.membership.domain.model; import com.gymmind.shared.persistence.TenantScopedEntity; import jakarta.persistence.*; import java.math.BigDecimal; @Entity @Table(name="membership_order") public class Order extends TenantScopedEntity{ @Column(name="member_id",nullable=false)private Long memberId;@Column(nullable=false,precision=12,scale=2)private BigDecimal total;@Column(nullable=false,length=3)private String currency;@Enumerated(EnumType.STRING)@Column(nullable=false,length=16)private OrderStatus status=OrderStatus.DRAFT;protected Order(){}private Order(Long t,Long m,BigDecimal a,String c){super(t);if(m==null||a==null||a.signum()<0||c==null||c.length()!=3)throw new IllegalArgumentException("Invalid order");memberId=m;total=a;currency=c.toUpperCase();}public static Order create(Long t,Long m,BigDecimal a,String c){return new Order(t,m,a,c);}public void place(){if(status!=OrderStatus.DRAFT)throw new IllegalStateException("Invalid order transition");status=OrderStatus.PLACED;}public void markPaid(){if(status!=OrderStatus.PLACED)throw new IllegalStateException("Invalid order transition");status=OrderStatus.PAID;}public void cancel(){if(status==OrderStatus.PAID||status==OrderStatus.REFUNDED)throw new IllegalStateException("Invalid order transition");status=OrderStatus.CANCELLED;}public Long getMemberId(){return memberId;}public BigDecimal getTotal(){return total;}public String getCurrency(){return currency;}public OrderStatus getStatus(){return status;}}
